/**
 * billing-smoke — exercises the 722lic.works API from inside the VPC.
 *
 * The billing API key is IP-pinned to the NAT EIP, so a laptop cannot test
 * it. This Lambda shares the orchestrator's egress and is the post-deploy
 * smoke test for the billing client (implementation plan D5, W1).
 *
 * No API route. Invoke directly:
 *   aws lambda invoke --function-name <name> --payload '{}' out.json
 *
 * Optional event fields:
 *   { "customerId": 123, "userCount": 150, "discountCode": "WELCOME20",
 *     "productCode": "AWS" }
 * When customerId is given, a yearly quote is also run (writes nothing).
 * Product code defaults to "AWS" (Kelly, 2026-10-04: AWS-REG is retired for
 * self-signup; AWS allows monthly and yearly). The pricing step lists every
 * product so AWS, AWS-IP and aPV can be checked by eye.
 *
 * Never logs or returns the API key.
 */

import { whoAmI, getPricing, quoteNewLicense } from "../shared/billing/client.mjs";
import { BillingError } from "../shared/billing/errors.mjs";

const step = async (name, fn) => {
  const started = Date.now();
  try {
    const result = await fn();
    return { name, ok: true, ms: Date.now() - started, result };
  } catch (err) {
    const e = err instanceof BillingError
      ? { code: err.code, status: err.status, extra: err.extra }
      : { code: "unexpected", message: err?.message };
    return { name, ok: false, ms: Date.now() - started, error: e };
  }
};

export const handler = async (event = {}) => {
  const steps = [];

  steps.push(
    await step("whoami", async () => {
      const me = await whoAmI();
      // Keep only scope-identifying fields.
      return {
        role: me?.role,
        scope_level: me?.scope_level,
        it_service_org_id: me?.it_service_org_id,
        product_line_id: me?.product_line_id,
      };
    })
  );

  steps.push(
    await step("pricing", async () => {
      const p = await getPricing();
      return {
        product_count: p?.product_count,
        products: (p?.products || []).map((x) => ({
          product_code: x.product_code,
          pricing_mode: x.pricing_mode,
          allow_yearly: x.allow_yearly,
          tier_count: (x.tiers || []).length,
        })),
      };
    })
  );

  if (event.customerId) {
    steps.push(
      await step("quote_yearly", async () => {
        const q = await quoteNewLicense({
          customerId: Number(event.customerId),
          productCode: event.productCode || "AWS",
          billingCadence: "yearly",
          userCount: Number(event.userCount || 150),
          discountCode: event.discountCode,
        });
        return {
          total_due_cents: q?.total_due_cents,
          amount_due_cents: q?.amount_due_cents,
          monthly_alternate_total_due_cents: q?.alternate_cadence?.total_due_cents,
          warnings: q?.warnings,
        };
      })
    );
  }

  const ok = steps.every((s) => s.ok);
  return {
    ok,
    base: process.env.BILLING_BASE_URL,
    installUrl: process.env.BILLING_INSTALL_URL,
    steps,
  };
};
