/**
 * Billing errors and their mapping to HTTP status + user-facing message.
 *
 * Every failure path from client.mjs produces a BillingError with a stable
 * `code`. The setup API maps `code` to what the wizard shows (D3). Keep
 * this table complete: an unknown code falls back to a generic message.
 */

const HELP = "Please try again in a few minutes. If it keeps failing, contact the help desk.";

/** code -> { status, userMessage } */
export const BILLING_ERROR_TABLE = {
  // Configuration / infrastructure (no external side effect yet)
  misconfigured: {
    status: 500,
    userMessage: `Billing is not configured. ${HELP}`,
  },
  secret_unavailable: {
    status: 503,
    userMessage: `Billing service is temporarily unavailable. ${HELP}`,
  },
  timeout: {
    status: 504,
    userMessage: `Billing service did not respond in time. ${HELP}`,
  },
  network: {
    status: 502,
    userMessage: `Could not reach the billing service. ${HELP}`,
  },
  upstream_5xx: {
    status: 502,
    userMessage: `Billing service returned an error. ${HELP}`,
  },

  // Request-level (4xx) — mapped from the platform's `detail`
  bad_discount_code: {
    status: 400,
    userMessage: "That promo code is not valid, has expired, or is inactive.",
  },
  validation: {
    status: 400,
    userMessage: "The billing service rejected the request. Please check your selection.",
  },
  unauthorized: {
    status: 502,
    userMessage: `Billing credentials were rejected. ${HELP}`,
  },
  forbidden: {
    status: 502,
    userMessage: `Billing access was refused for this account. ${HELP}`,
  },
  not_found: {
    status: 502,
    userMessage: `A billing record could not be found. ${HELP}`,
  },
  license_exists: {
    status: 409,
    userMessage: "A license already exists for this account.",
  },
  seat_change_blocked: {
    status: 400, // the platform refuses with 400; fromResponse keeps that status
    userMessage: "Seat changes are not available until the current term has been invoiced. Try again after the next billing run.",
  },
  nothing_to_backfill: {
    status: 400,
    userMessage: "Nothing to update.",
  },
  // change-plan (3.8): the platform's other 400s here are business rules
  // (seat decrease, user_count on monthly, two non-monthly cadences,
  // invoice_lead_days, org volume-tier code), not malformed input. One
  // message covers them; the platform's text stays in the log (W9).
  plan_change_refused: {
    status: 400,
    userMessage: "The billing platform did not accept this plan change. Seat counts can only go up, and a monthly plan does not take a seat count. If the problem persists, contact support.",
  },

  unknown: {
    status: 502,
    userMessage: `Billing request failed. ${HELP}`,
  },
};

export class BillingError extends Error {
  /**
   * @param {string} code  key in BILLING_ERROR_TABLE
   * @param {number} [status] override HTTP status
   * @param {object} [extra] diagnostic fields (never shown to the user)
   */
  constructor(code, status, extra = {}) {
    const entry = BILLING_ERROR_TABLE[code] || BILLING_ERROR_TABLE.unknown;
    super(`billing:${code}`);
    this.name = "BillingError";
    this.code = BILLING_ERROR_TABLE[code] ? code : "unknown";
    this.status = status ?? entry.status;
    this.userMessage = entry.userMessage;
    this.extra = extra;
  }

  /** Classify a non-2xx platform response into a code. */
  static fromResponse(status, json, context) {
    const detail = String(json?.detail?.detail ?? json?.detail ?? "");
    const platformCode = json?.detail?.code ?? json?.code;
    let code = "unknown";

    if (status === 401) code = "unauthorized";
    else if (status === 403) code = "forbidden";
    else if (status === 404) code = "not_found";
    else if (status === 409) {
      code = platformCode === "license_exists" ? "license_exists" : "validation";
    } else if (status === 400) {
      // Order matters: the transient blocked-window text first, then every
      // change-plan context uniformly (a change-plan request carries no
      // discount code, so the promo message would mislead), then the rest.
      if (/seat changes are blocked/i.test(detail)) code = "seat_change_blocked";
      else if (typeof context === "string" && context.startsWith("change_plan")) code = "plan_change_refused";
      else if (/discount_code/i.test(detail)) code = "bad_discount_code";
      else code = "validation";
    } else if (status >= 500) code = "upstream_5xx";

    return new BillingError(code, status === 400 || status === 409 ? status : undefined, {
      httpStatus: status,
      detail: detail.slice(0, 500),
      platformCode,
      context,
    });
  }

  /** Shape for an API response body. */
  toResponseBody(requestId) {
    return {
      errorCode: `billing_${this.code}`,
      message: this.userMessage,
      requestId,
    };
  }
}
