/**
 * 722lic.works Licensing client (external API v1.82).
 *
 * Shared by the signup setup Lambda, the setup orchestrator, and the
 * billing-smoke Lambda. Bundled into each consumer by esbuild via
 * relative import (same pattern as ../dedicated-worker-routing.mjs).
 *
 * Contract source: docs/TENANT_SELF_SIGNUP_PLAN.md section 1.5
 * ("Current billing contract (v1.82.0)") and
 * docs/TENANT_SELF_SIGNUP_IMPLEMENTATION.md decisions D1, D2, D7.
 *
 * Environment:
 *   BILLING_BASE_URL   e.g. https://licdev.apersona.com:9443
 *   BILLING_INSTALL_URL the Installation URL sent as `url` on /v1 writes
 *   BILLING_SECRET_ID  Secrets Manager id holding the org-scoped API key
 *                      (default apersona/billing/apikey)
 */

import {
  SecretsManagerClient,
  GetSecretValueCommand,
} from "@aws-sdk/client-secrets-manager";
import { BillingError } from "./errors.mjs";

const API_PREFIX = "/license/api";
const DEFAULT_SECRET_ID = "apersona/billing/apikey";

// D1 timeouts (ms) and attempt counts.
const T = {
  create: { timeoutMs: 15_000, attempts: 3 },
  mutate: { timeoutMs: 10_000, attempts: 2 },
  read: { timeoutMs: 8_000, attempts: 1 },
};
const BACKOFF_MS = [1_000, 2_000];

// The secret read runs before the D1 attempt timer starts, so bound it
// here: 2 s to connect, 5 s per request, 2 attempts (cold start only;
// the key is cached afterwards). Worst case ~14 s, inside every caller's
// budget; D3 then fails fast with 503.
const secretsManager = new SecretsManagerClient({
  region: process.env.AWS_REGION,
  maxAttempts: 2,
  requestHandler: { connectionTimeout: 2_000, requestTimeout: 5_000 },
});

// Warm-start cache (asm-shared.mjs pattern). Rotation takes effect on the
// next cold start (D7).
let cachedApiKey = null;

export async function getApiKey() {
  if (cachedApiKey) return cachedApiKey;
  const secretId = process.env.BILLING_SECRET_ID || DEFAULT_SECRET_ID;
  try {
    const res = await secretsManager.send(
      new GetSecretValueCommand({ SecretId: secretId })
    );
    const value = (res.SecretString || "").trim();
    if (!value) throw new Error("empty secret");
    cachedApiKey = value;
    return cachedApiKey;
  } catch (err) {
    // D3: fail fast, no external side effect has happened yet.
    throw new BillingError("secret_unavailable", 503, {
      cause: err?.name || String(err),
    });
  }
}

/** Test hook: drop the cached key. */
export function _resetApiKeyCache() {
  cachedApiKey = null;
}

function baseUrl() {
  const b = process.env.BILLING_BASE_URL;
  if (!b) throw new BillingError("misconfigured", 500, { missing: "BILLING_BASE_URL" });
  return b.replace(/\/+$/, "");
}

function installUrl() {
  const u = process.env.BILLING_INSTALL_URL;
  if (!u) throw new BillingError("misconfigured", 500, { missing: "BILLING_INSTALL_URL" });
  return u;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/**
 * Replace every occurrence of `secret` in `text`: raw, and URL-encoded with
 * either case of percent escapes (`%2F` and `%2f`), all matched
 * case-insensitively (codex W17 round 5 P1).
 */
export function redactSecret(text, secret) {
  if (!text || !secret) return text;
  const esc = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const forms = [secret];
  const enc = encodeURIComponent(secret);
  if (enc !== secret) forms.push(enc);
  return forms.reduce((out, f) => out.replace(new RegExp(esc(f), "gi"), "(redacted)"), text);
}

/** Below this much remaining budget a call is not started: a side effect the caller can no longer report is worse than a clean 504. */
export const MIN_ATTEMPT_MS = 1_500;

/**
 * One HTTP call with timeout and D1 retry policy. Retries only on
 * network error, timeout, or 5xx. Never retries 4xx (409 is a success
 * path for createLicense and is handled by the caller).
 *
 * `deadlineAt` (absolute ms, optional) clamps every attempt to the budget
 * left and refuses to start an attempt or a retry with less than
 * MIN_ATTEMPT_MS remaining. A synchronous route (API Gateway cuts off at
 * 30 s) passes its own deadline so an apply cannot land on the platform
 * after the browser has already been told the request timed out (codex
 * W17 round 1 P1). Without it the D1 policy alone applies (orchestrator).
 */
async function request(method, path, body, policy, { expectJson = true, deadlineAt } = {}) {
  const remaining = () => (deadlineAt === undefined ? Infinity : deadlineAt - Date.now());
  if (remaining() < MIN_ATTEMPT_MS) throw new BillingError("timeout", undefined, { cause: "route budget exhausted before the secret read" });
  const apiKey = await getApiKey();
  const url = `${baseUrl()}${API_PREFIX}${path}`;
  let lastErr;

  for (let attempt = 0; attempt < policy.attempts; attempt++) {
    if (remaining() < MIN_ATTEMPT_MS) {
      throw lastErr ?? new BillingError("timeout", undefined, { cause: "route budget exhausted before the first attempt" });
    }
    const ctrl = new AbortController();
    // The timer covers the whole attempt, body read included: a stalled
    // body must not eat the orchestrator's budget after a side effect.
    const timer = setTimeout(() => ctrl.abort(), Math.min(policy.timeoutMs, remaining()));
    try {
      const res = await fetch(url, {
        method,
        headers: {
          "X-Aplicense-Admin-Key": apiKey,
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: ctrl.signal,
      });

      // The platform's free text may echo request headers; the API key must
      // never reach a log or an Error (W9). Redacted here, once, for every
      // caller (codex W17 round 4 P1).
      const text = redactSecret(await res.text(), apiKey);
      let json = null;
      if (expectJson && text) {
        try {
          json = JSON.parse(text);
        } catch {
          json = { detail: text };
        }
      }

      if (res.status >= 500) {
        lastErr = new BillingError("upstream_5xx", 502, {
          status: res.status,
          detail: json?.detail,
        });
        // fall through to retry
      } else {
        return { status: res.status, json };
      }
    } catch (err) {
      // Status from the table: 504 for a timeout, 502 for a network failure.
      lastErr = new BillingError(err?.name === "AbortError" ? "timeout" : "network", undefined, {
        cause: err?.message || String(err),
      });
    } finally {
      clearTimeout(timer);
    }
    if (attempt < policy.attempts - 1) {
      const backoff = BACKOFF_MS[Math.min(attempt, BACKOFF_MS.length - 1)];
      if (remaining() - backoff < MIN_ATTEMPT_MS) break; // no room for a retry after the pause
      await sleep(backoff);
    }
  }
  throw lastErr;
}

/** Throw a mapped BillingError for any non-2xx response. */
function assertOk(resp, context) {
  if (resp.status >= 200 && resp.status < 300) return resp.json;
  throw BillingError.fromResponse(resp.status, resp.json, context);
}

// ---------------------------------------------------------------------------
// Reads
// ---------------------------------------------------------------------------

/** Who am I — verifies key and scope. */
export async function whoAmI() {
  const resp = await request("GET", "/me", undefined, T.read);
  return assertOk(resp, "whoami");
}

/** Current price list for the key's Product Line (v1.50.0). */
export async function getPricing() {
  const resp = await request("GET", "/v1/pricing", undefined, T.read);
  return assertOk(resp, "pricing");
}

/**
 * Quote a not-yet-created license (v1.39.0). Writes nothing.
 * For a monthly cap price, quote yearly at `user_count` and read
 * `alternate_cadence` from the result (D4 / §6B A2).
 */
export async function quoteNewLicense({
  customerId,
  productCode,
  billingCadence,
  userCount,
  discountCode,
}) {
  const body = {
    url: installUrl(),
    customer_id: customerId,
    product_code: productCode,
    billing_cadence: billingCadence,
  };
  if (userCount !== undefined) body.user_count = userCount;
  if (discountCode) body.discount_code = discountCode;
  const resp = await request("POST", "/v1/licenses/quote", body, T.read);
  return assertOk(resp, "quote");
}

export async function getLicense(licenseId, { deadlineAt } = {}) {
  const resp = await request("GET", `/v1/licenses/${licenseId}`, undefined, T.read, { deadlineAt });
  return assertOk(resp, "get_license");
}

export async function listLicenses({ customerId, productCode } = {}) {
  const q = new URLSearchParams();
  if (customerId !== undefined) q.set("customer_id", String(customerId));
  if (productCode) q.set("product_code", productCode);
  const qs = q.toString();
  const resp = await request("GET", `/v1/licenses${qs ? `?${qs}` : ""}`, undefined, T.read);
  return assertOk(resp, "list_licenses");
}

// ---------------------------------------------------------------------------
// Writes
// ---------------------------------------------------------------------------

/**
 * Build the cadence-correct seat field (v1.82): monthly -> allowed_users,
 * every other cadence -> user_count. Sending the wrong one is a 400.
 */
export function seatFieldFor(billingCadence, seats) {
  return billingCadence === "monthly"
    ? { allowed_users: seats }
    : { user_count: seats };
}

/**
 * Create a license as `pending` (nothing bills; ASM serves 5 users free
 * until activation). Safe to retry: a 409 `license_exists` returns the
 * existing license in the body.
 *
 * Returns { license, created } where created=false means a 409 was
 * returned and `license` is the existing one. D2 branching (revoke a
 * mismatched pending license and recreate) is the caller's decision
 * because it needs the saved selection; see resolveLicenseFor409().
 */
export async function createPendingLicense({
  customerId,
  productCode,
  billingCadence,
  seats,
  discountCode,
  expirationDate,
  renewalMode = "auto_perpetual",
}) {
  const body = {
    url: installUrl(),
    customer_id: customerId,
    product_code: productCode,
    billing_cadence: billingCadence,
    expiration_date: expirationDate,
    status: "pending",
    renewal_mode: renewalMode,
    ...seatFieldFor(billingCadence, seats),
  };
  if (discountCode) body.discount_code = discountCode;

  const resp = await request("POST", "/v1/licenses", body, T.create);
  if (resp.status === 409) {
    // Body shape seen in §6B A3: {detail: {detail, code, existing}} or flat.
    const inner = resp.json?.detail?.existing ? resp.json.detail : resp.json;
    if (inner?.code === "license_exists" && inner?.existing) {
      return { license: inner.existing, created: false };
    }
    throw BillingError.fromResponse(409, resp.json, "create_license");
  }
  return { license: assertOk(resp, "create_license"), created: true };
}

/** Status-only PATCH. `active` makes the platform set paid_through_date. */
async function setStatus(licenseId, status) {
  const resp = await request(
    "PATCH",
    `/v1/licenses/${licenseId}`,
    { status },
    T.mutate
  );
  return assertOk(resp, `set_status_${status}`);
}

export const activateLicense = (licenseId) => setStatus(licenseId, "active");
export const revokeLicense = (licenseId) => setStatus(licenseId, "revoked");

/**
 * Plan change (design doc 3.8, 1.5 `POST /v1/licenses/{id}/change-plan`,
 * v1.41.0): cadence switch and/or seat count in one call. `preview: true`
 * runs the platform's pricing path without writing and is the read the
 * Plan page shows before apply (a yearly seat increase is invoiced
 * immediately, Q34a). Cadence changes are deferred by the platform and
 * charge nothing at submit time.
 *
 * Seat field: yearly -> `user_count`; a monthly target takes NO seat field
 * (the platform refuses `user_count` there and keeps the cap itself,
 * Q34b), so passing `seats` with monthly is rejected here as misuse.
 * Monthly -> yearly must pass `seats` (3.8: never rely on the platform's
 * peak-based default). An apply is a mutate (D1: 2 attempts); a preview
 * is a read (1 attempt).
 */
export async function changePlan(licenseId, { billingCadence, seats, preview = false, deadlineAt }) {
  if (billingCadence === "monthly" && seats !== undefined) {
    // Programmer error, not a platform refusal: 3.8 never sends a seat
    // field to monthly (the platform keeps the cap across the switch, Q34b).
    throw new TypeError("changePlan: a monthly target takes no seat count");
  }
  const body = { billing_cadence: billingCadence, preview: preview === true };
  if (seats !== undefined) Object.assign(body, seatFieldFor(billingCadence, seats));
  const resp = await request(
    "POST",
    `/v1/licenses/${licenseId}/change-plan`,
    body,
    preview ? T.read : T.mutate,
    { deadlineAt }
  );
  return assertOk(resp, preview ? "change_plan_preview" : "change_plan");
}

/** Cancel a pending (deferred) plan change: `{cancel_pending: true}` (1.5). */
export async function cancelPlanChange(licenseId, { deadlineAt } = {}) {
  const resp = await request(
    "POST",
    `/v1/licenses/${licenseId}/change-plan`,
    { cancel_pending: true },
    T.mutate,
    { deadlineAt }
  );
  return assertOk(resp, "change_plan_cancel");
}

/** Monthly-only seat cap (v1.63.0). 400 on any other cadence. */
export async function setAllowedUsers(licenseId, allowedUsers) {
  const resp = await request(
    "PATCH",
    `/v1/licenses/${licenseId}/allowed-users`,
    { allowed_users: allowedUsers },
    T.mutate
  );
  return assertOk(resp, "set_allowed_users");
}

/**
 * Backfill the three provisioning IDs. Omit keys you do not have:
 * an empty string or null CLEARS the field on the platform.
 */
export async function patchCustomerIds(customerId, { asmTenantId, awsTenantId, providerId }) {
  const body = {};
  if (asmTenantId) body.asm_tenant_id = String(asmTenantId);
  if (awsTenantId) body.aws_tenant_id = String(awsTenantId);
  if (providerId) body.provider_id = String(providerId);
  if (Object.keys(body).length === 0) {
    throw new BillingError("nothing_to_backfill", 400);
  }
  const resp = await request("PATCH", `/v1/customers/${customerId}`, body, T.mutate);
  return assertOk(resp, "patch_customer");
}

// ---------------------------------------------------------------------------
// D2: what to do with a 409 existing license
// ---------------------------------------------------------------------------

/**
 * Compare an existing license with the current selection: cadence, seats
 * AND promo code (D2 "mismatched with the current selection"; a different
 * promo on a pending license would be billed at the wrong price, so it
 * counts as a mismatch — codex design review 2026-10-03 #8).
 */
export function licenseMatchesSelection(license, { billingCadence, seats, discountCode }) {
  if (license.billing_cadence !== billingCadence) return false;
  const existingSeats =
    billingCadence === "monthly" ? license.allowed_users : license.user_count;
  if (Number(existingSeats) !== Number(seats)) return false;
  return (license.discount_code || null) === (discountCode || null);
}

/**
 * D2 decision for a 409 result.
 *   - existing.status === "pending" and mismatched -> "recreate"
 *     (caller revokes it, then creates again)
 *   - existing.status === "pending" and matching  -> "reuse"
 *   - existing.status === "active"                -> "reuse" (a prior run
 *     already activated; log the mismatch, never recreate)
 *   - anything else (suspended, revoked, unknown) -> "fail": D2 defines no
 *     safe behaviour, so the orchestrator parks the signup with the
 *     status in the error instead of silently reusing the license.
 */
export function resolveLicenseFor409(existing, selection) {
  const matches = licenseMatchesSelection(existing, selection);
  if (existing.status === "pending") {
    return matches ? { action: "reuse", mismatch: false } : { action: "recreate", mismatch: true };
  }
  if (existing.status === "active") return { action: "reuse", mismatch: !matches };
  return { action: "fail", mismatch: !matches, status: existing.status };
}
